  ('GMRC', 5, 'G5-001', 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iingat at pagpapabuti ng sariling buhay. - Naiisa-isa ang mga kilos na nagpapahalaga sa sariling buhay.', 1, '1 to 2 (10 days)', NULL),
  ('GMRC', 5, 'G5-002', 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iingat at pagpapabuti ng sariling buhay. - Naipaliliwanag na ang mga kilos na nagpapahalaga sa sariling buhay ay paraan upang kilalanin ang sariling dignidad bilang tao at ang mga salik na nakaaapekto sa pagtataguyod nito.', 1, '1 to 2 (10 days)', NULL),
  ('GMRC', 5, 'G5-003', 'Nakapagsasanay sa paggalang sa buhay sa pamamagitan ng pag-iingat at pagpapabuti ng sariling buhay. - Nailalapat ang mga kilos na nagpapahalaga sa sariling buhay bilang pagkilala sa kaniyang dignidad.', 1, '1 to 2 (10 days)', NULL),
  ('GMRC', 5, 'G5-004', 'Nakapagsasanay sa pagpapahalaga sa sarili sa pamamagitan ng pagsunod batay sa mga isinangguni sa mga magulang, nakatatanda, tagapangalaga o taong pinagkakatiwalaan. - Natutukoy ang mga pagbabagong nararanasan sa sarili.', 1, '3 to 4 (10 days)', NULL),
  ('GMRC', 5, 'G5-005', 'Nakapagsasanay sa pagpapahalaga sa sarili sa pamamagitan ng pagsunod batay sa mga isinangguni sa mga magulang, nakatatanda, tagapangalaga o taong pinagkakatiwalaan. - Nasusuri na ang mga pagbabagong nagaganap sa sarili ay bahagi ng kanilang pag-unlad bilang tao at paghahanda para sa mga susunod na yugto ng buhay.', 1, '3 to 4 (10 days)', NULL),
  ('GMRC', 5, 'G5-006', 'Nakapagsasanay sa pagpapahalaga sa sarili sa pamamagitan ng pagsunod batay sa mga isinangguni sa mga magulang, nakatatanda, tagapangalaga o taong pinagkakatiwalaan. - Nailalapat ang mga paraan ng pangangalaga sa sarili habang nararanasan ang mga pagbabago sa tulong ng pamilya.', 1, '3 to 4 (10 days)', NULL),
  ('GMRC', 5, 'G5-007', 'Nakapagsasanay sa pagiging maagap sa pamamagitan ng pagtupad ng plano ng pagkonsumo o paggastos sa loob ng isang linggo nang may pagsasaalang-alang sa mga bagay na iipunin ayon sa sariling kakayahan. - Nailalarawan ang mga gawain ng pag-iimpok para sa sariling kinabukasan.', 1, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-008', 'Nakapagsasanay sa pagiging maagap sa pamamagitan ng pagtupad ng plano ng pagkonsumo o paggastos sa loob ng isang linggo nang may pagsasaalang-alang sa mga bagay na iipunin ayon sa sariling kakayahan. - Naipaliliwanag na ang pag-iimpok bilang paghahanda sa sariling kinabukasan ay kailangang malinang upang matugunan ang mga kakaharaping pangangailangan sa iba’t ibang sitwasyon.', 1, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-009', 'Nakapagsasanay sa pagiging maagap sa pamamagitan ng pagtupad ng plano ng pagkonsumo o paggastos sa loob ng isang linggo nang may pagsasaalang-alang sa mga bagay na iipunin ayon sa sariling kakayahan. - Nakapaglalapat ng mga gawaing pag-iimpok para sa sariling kinabukasan.', 1, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-010', 'Naisasabuhay ang pananampalataya sa pamamagitan ng paglalaan ng oras ng pananalangin at pagbabasa ng mga Banal na Aklat. - Naiisa-isa ang mga kahalagahan ng sariling pananampalataya.', 1, '6 to 7 (10 days)', NULL),
  ('GMRC', 5, 'G5-011', 'Naisasabuhay ang pananampalataya sa pamamagitan ng paglalaan ng oras ng pananalangin at pagbabasa ng mga Banal na Aklat. - Nahihinuha na ang kahalagahan ng sariling pananampalataya ay nagpapatatag ng kalooban na pinanggagalingan ng wastong asal at pag-alam ng mabuti at masama.', 1, '6 to 7 (10 days)', NULL),
  ('GMRC', 5, 'G5-012', 'Naisasabuhay ang pananampalataya sa pamamagitan ng paglalaan ng oras ng pananalangin at pagbabasa ng mga Banal na Aklat. - Nakabubuo ng repleksiyon o mga paraan ng pagbibigay-halaga sa sariling pananampalataya.', 1, '6 to 7 (10 days)', NULL),
  ('GMRC', 5, 'G5-013', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng paglalaan ng regular na panahon sa pagbabasa o pagninilay sa nilalaman ng Banal na Aklat, babasahin o katumbas nito ng sariling pananampalataya o paniniwala. - Naiisa-isa ang mga kahalagahan ng Banal na Aklat, babasahin o katumbas nito sa sariling pananampalataya o paniniwala.', 1, '8 to 9 (10 days)', NULL),
  ('GMRC', 5, 'G5-014', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng paglalaan ng regular na panahon sa pagbabasa o pagninilay sa nilalaman ng Banal na Aklat, babasahin o katumbas nito ng sariling pananampalataya o paniniwala. - Naipaliliwanag na ang kahalagahan ng Banal na Aklat, babasahin o katumbas nito sa sariling pananampalataya o paniniwala ay mahalagang paraan upang maingatan at mapalalim ang kaniyang pag-unawa sa mga mahalagang aral ng kinabibilangang relihiyon.', 1, '8 to 9 (10 days)', NULL),
  ('GMRC', 5, 'G5-015', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng paglalaan ng regular na panahon sa pagbabasa o pagninilay sa nilalaman ng Banal na Aklat, babasahin o katumbas nito ng sariling pananampalataya o paniniwala. - Naisasakilos ang wastong paggamit at pag-iingat ng Banal na Aklat, babasahin o katumbas nito ng sariling pananampalataya o paniniwala.', 1, '8 to 9 (10 days)', NULL),
  ('GMRC', 5, 'G5-016', 'Naipakikita ang pagiging masinop sa pamamagitan ng paggugol ng sapat na panahon at lakas sa pagtatapon o pagreresiklo ng mga gamit-teknolohikal nang may pagsasaalang-alang sa kaligtasan at kakayahan. - Nakapaghahayag ng mga wastong paraan ng sariling pamamahala sa mga patapong gamit- teknolohikal.', 1, '10 (5 days)', NULL),
  ('GMRC', 5, 'G5-017', 'Naipakikita ang pagiging masinop sa pamamagitan ng paggugol ng sapat na panahon at lakas sa pagtatapon o pagreresiklo ng mga gamit-teknolohikal nang may pagsasaalang-alang sa kaligtasan at kakayahan. - Nahihinuha na ang sariling pamamahala sa mga patapong gamit- teknolohikal ay pagtitiyak ng kaligtasan at kalusugan ng kalikasan at tao.', 1, '10 (5 days)', NULL),
  ('GMRC', 5, 'G5-018', 'Naipakikita ang pagiging masinop sa pamamagitan ng paggugol ng sapat na panahon at lakas sa pagtatapon o pagreresiklo ng mga gamit-teknolohikal nang may pagsasaalang-alang sa kaligtasan at kakayahan. - Nailalapat ang mga wastong paraan ng sariling pamamahala sa mga patapong gamit-teknolohikal.', 1, '10 (5 days)', NULL),
  ('GMRC', 5, 'G5-019', 'Nakapagsasanay ng pagiging masunurin sa pamamagitan ng wastong pagtugon sa mga paalala at babala sa daan (road sign). - Nakakikilala ng mga sariling tungkulin sa batas trapiko sa pamayanan.', 1, '11 (5 days)', NULL),
  ('GMRC', 5, 'G5-020', 'Nakapagsasanay ng pagiging masunurin sa pamamagitan ng wastong pagtugon sa mga paalala at babala sa daan (road sign). - Nasusuri na ang mga sariling tungkulin sa batas trapiko sa pamayanan ay paraan upang tiyakin ang kaligtasan ng lahat at malinang ang pagiging mabuting mamamayan.', 1, '11 (5 days)', NULL),
  ('GMRC', 5, 'G5-021', 'Nakapagsasanay ng pagiging masunurin sa pamamagitan ng wastong pagtugon sa mga paalala at babala sa daan (road sign). - Naisasakilos ang mga wastong paraan ng pagsunod sa batas trapiko.', 1, '11 (5 days)', NULL),
  ('GMRC', 5, 'G5-022', 'Naipakikita ang pagiging mapagpasalamat sa pamamagitan ng pagdakila sa mga mabuting ginawa ng kaniyang mga magulang o tagapangalaga. - Nakapagpapahayag ng mga sariling paraan ng pagmamahal sa mga magulang o tagapangalaga.', 1, '12 to 13 (9 days)', NULL),
  ('GMRC', 5, 'G5-023', 'Naipakikita ang pagiging mapagpasalamat sa pamamagitan ng pagdakila sa mga mabuting ginawa ng kaniyang mga magulang o tagapangalaga. - Napatutunayan na ang mga sariling paraan ng pagmamahal sa mga magulang o tagapangalaga ay bahagi ng pagpapahalaga sa kanilang tungkulin at sakripisyo tungo sa pagpapatatag ng ugnayan ng bawat kasapi ng pamilya.', 1, '12 to 13 (9 days)', NULL),
  ('GMRC', 5, 'G5-024', 'Naipakikita ang pagiging mapagpasalamat sa pamamagitan ng pagdakila sa mga mabuting ginawa ng kaniyang mga magulang o tagapangalaga. - Nailalapat ang mga sariling paraan ng pagmamahal sa mga magulang o tagapangalaga.', 1, '12 to 13 (9 days)', NULL),
  ('GMRC', 5, 'G5-025', 'Naisasabuhay ang pagiging mapagmalasakit sa pamamagitan ng pag-aalaga sa may-sakit, pag-alalay sa mga nakatatanda, Persons with Disability (PWD), at mga taong may natatanging kondisyon. - Nakapagpapahayag ng iba’t ibang paraan ng pagkalinga sa kapuwa.', 2, '1 (5 days)', NULL),
  ('GMRC', 5, 'G5-026', 'Naisasabuhay ang pagiging mapagmalasakit sa pamamagitan ng pag-aalaga sa may-sakit, pag-alalay sa mga nakatatanda, Persons with Disability (PWD), at mga taong may natatanging kondisyon. - Naipaliliwanag na ang pagkalinga sa kapuwa ay bahagi ng sariling tungkulin na tumulong bilang pagbibigay halaga sa buhay ayon sa kakayahan.', 2, '1 (5 days)', NULL),
  ('GMRC', 5, 'G5-027', 'Naisasabuhay ang pagiging mapagmalasakit sa pamamagitan ng pag-aalaga sa may-sakit, pag-alalay sa mga nakatatanda, Persons with Disability (PWD), at mga taong may natatanging kondisyon. - Nailalapat ang mga kilos ng pagkalinga sa kapuwa ng may pagsasaalang-alang sa kaangkupan ng sitwasyon.', 2, '1 (5 days)', NULL),
  ('GMRC', 5, 'G5-028', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng pagninilay sa kanilang mga hirap at tagumpay. - Nakakikilala sa mga ambag ng mga nangingibang bansa o Overseas Filipino Workers (OFWs) sa pag-unlad ng bayan.', 2, '2 to 3 (10 days)', NULL),
  ('GMRC', 5, 'G5-029', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng pagninilay sa kanilang mga hirap at tagumpay. - Naipaliliwanag na ang sariling pagpapahalaga sa mga ambag ng mga nangingibang-bansa o Overseas Filipino Workers (OFWs) ay pagkilala sa kanilang mga sakripisyo at kabayanihan na itaguyod ang kanilang pamilya na makatutulong sa kabuhayan ng bansa.', 2, '2 to 3 (10 days)', NULL),
  ('GMRC', 5, 'G5-030', 'Naisasabuhay ang pagiging mapagpasalamat sa pamamagitan ng pagninilay sa kanilang mga hirap at tagumpay. - Naisasakilos ang mga paraan ng sariling pagpapahalaga sa mga ambag ng mga nangingibang- bansa o Overseas Filipino Workers (OFWs).', 2, '2 to 3 (10 days)', NULL),
  ('GMRC', 5, 'G5-031', 'Nakapagsasanay sa pagiging magalang sa pamamagitan ng bukas na pagtanggap sa bawat kasapi ng pamilya. - Natutukoy ang mga katangian ng pamilyang kinabibilangan.', 2, '4 (5 days)', NULL),
  ('GMRC', 5, 'G5-032', 'Nakapagsasanay sa pagiging magalang sa pamamagitan ng bukas na pagtanggap sa bawat kasapi ng pamilya. - Naipaliliwanag na ang pagkilala sa pamilyang kinabibilangan ay mahalaga upang mapagtibay ang ugnayan ng pamilya.', 2, '4 (5 days)', NULL),
  ('GMRC', 5, 'G5-033', 'Nakapagsasanay sa pagiging magalang sa pamamagitan ng bukas na pagtanggap sa bawat kasapi ng pamilya. - Nakabubuo ng representasyon ng bawat kasapi ng pamilyang kinabibilangan na nagpapakita ng gawi, wika, pagpapahalaga o ugnayan batay sa kaniyang kakayahan.', 2, '4 (5 days)', NULL),
  ('GMRC', 5, 'G5-034', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagbibigay-halaga sa epekto ng kanilang tungkulin sa pamilya. - Natutukoy ang mga tungkulin ng bawat kasapi ng pamilyang kinabibilangan.', 2, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-035', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagbibigay-halaga sa epekto ng kanilang tungkulin sa pamilya. - Naipaliliwanag na ang tungkulin ng bawat kasapi ng pamilya ay mahalagang gampanan nang maayos upang mapagaan ang kanilang mga gawain at kakayahang mapamahalaan ang sarili.', 2, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-036', 'Naisasabuhay ang pagiging mapanagutan sa pamamagitan ng pagbibigay-halaga sa epekto ng kanilang tungkulin sa pamilya. - Nailalapat ang mga paraan ng pagtupad ng sariling tungkulin bilang kasapi ng pamilya.', 2, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-037', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng pagkikilahok sa mga gawain panrelihiyon o paniniwalang kinabibilangan kasama ang pamilya. - Nakakikilala ng mga tungkulin ng pamilya sa paglinang ng pananampalataya.', 2, '6 to 7 (10 days)', NULL),
  ('GMRC', 5, 'G5-038', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng pagkikilahok sa mga gawain panrelihiyon o paniniwalang kinabibilangan kasama ang pamilya. - Naipaliliwanag na ang mga tungkulin ng pamilya sa paglinang ng pananampalataya ay dapat gampanan nang sama-sama upang mapatatag ang ugnayan sa Diyos, kumiling ang mga kasapi sa kabutihan, at mapanatag ang kanilang kalooban sa pagharap sa mga hamon ng buhay.', 2, '6 to 7 (10 days)', NULL),
  ('GMRC', 5, 'G5-039', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng pagkikilahok sa mga gawain panrelihiyon o paniniwalang kinabibilangan kasama ang pamilya. - Nailalapat ang mga sariling paraan ng pagtupad sa tungkulin ng pamilya sa paglinang ng pananampalataya.', 2, '6 to 7 (10 days)', NULL),
  ('GMRC', 5, 'G5-040', 'Nakapagsasanay sa pagiging mapagpasalamat sa pamamagitan ng pagbibigay-halaga at pag-iingat sa mga biyayang natatangap ng pamilya. - Nakakikilala ng mga paraan ng pasasalamat sa Diyos sa mga biyayang natatanggap ng pamilya.', 2, '8 to 9 (8 days)', NULL),
  ('GMRC', 5, 'G5-041', 'Nakapagsasanay sa pagiging mapagpasalamat sa pamamagitan ng pagbibigay-halaga at pag-iingat sa mga biyayang natatangap ng pamilya. - Naipaliliwanag na ang pasasalamat sa Diyos sa mga biyayang natatanggap ng pamilya ay paraan ng pagbibigay-halaga sa Kaniyang kabutihan at pagkilala na mula sa Diyos ang lahat ng mga nakakamit ng tao.', 2, '8 to 9 (8 days)', NULL),
  ('GMRC', 5, 'G5-042', 'Nakapagsasanay sa pagiging mapagpasalamat sa pamamagitan ng pagbibigay-halaga at pag-iingat sa mga biyayang natatangap ng pamilya. - Naisasakilos ang mga sariling paraan ng pasasalamat sa Diyos sa mga biyayang natatanggap ng pamilya.', 2, '8 to 9 (8 days)', NULL),
  ('GMRC', 5, 'G5-043', 'Naisasabuhay ang pagiging malinis sa pamamagitan ng palagiang pag-aalis ng mga bagay na hindi na kailangan upang mapakibangan ng iba. - Naiisa-isa ang mga paraan ng pagpapanatili nang kalinisan at kaayusan ng tahanan.', 2, '10 (4 days)', NULL),
  ('GMRC', 5, 'G5-044', 'Naisasabuhay ang pagiging malinis sa pamamagitan ng palagiang pag-aalis ng mga bagay na hindi na kailangan upang mapakibangan ng iba. - Naipaliliwanag na ang pagpapanatili ng kalinisan at kaayusan sa tahanan ay nakapagdudulot ng kalusugang pangkaisipan at pangkatawan,kaligtasan, at maayos na ugnayan ng mga kasapi ng pamilya.', 2, '10 (4 days)', NULL),
  ('GMRC', 5, 'G5-045', 'Naisasabuhay ang pagiging malinis sa pamamagitan ng palagiang pag-aalis ng mga bagay na hindi na kailangan upang mapakibangan ng iba. - Naisasakilos ang mga paraan ng pagpapanatili ng kalinisan at kaayusan sa tahanan.', 2, '10 (4 days)', NULL),
  ('GMRC', 5, 'G5-046', 'Naisasabuhay ang nasyonalismo sa pamamagitan ng pagpapalaganap ng kalidad ng mga lokal na produkto upang tangkilikin ang mga ito ng mga mamamayan. - Naiisa-isa ang mga paraan ng pagtangkilik ng pamilya sa mga lokal na produkto.', 2, '11 to 12 (10 days)', NULL),
  ('GMRC', 5, 'G5-047', 'Naisasabuhay ang nasyonalismo sa pamamagitan ng pagpapalaganap ng kalidad ng mga lokal na produkto upang tangkilikin ang mga ito ng mga mamamayan. - Naipaliliwanag na ang pagtangkilik ng pamilya sa mga lokal na produkto ay mahalagang kontribusyon sa pagtataguyod ng mga gawang Pilipino at sumasalamin sa pakikiisa sa kulturang nagbibigkis sa mamamayan.', 2, '11 to 12 (10 days)', NULL),
  ('GMRC', 5, 'G5-048', 'Naisasabuhay ang nasyonalismo sa pamamagitan ng pagpapalaganap ng kalidad ng mga lokal na produkto upang tangkilikin ang mga ito ng mga mamamayan. - Nailalapat ang sariling mga paraan ng pagtangkilik ng pamilya sa mga lokal na produkto.', 2, '11 to 12 (10 days)', NULL),
  ('GMRC', 5, 'G5-049', 'Naipakikita ang pagiging mapagpasensiya sa pamamagitan ng pagpapakalma ng sarili kung kinakailangan o pag-iwas sa mga situwasyong pumupukaw ng negatibong reaksiyon. - Nailalarawan ang mga wastong paraan ng pamamahala sa sariling emosyon na nakaaapekto sa pakikipagkapuwa.', 2, '13 (3 days)', NULL),
  ('GMRC', 5, 'G5-050', 'Naipakikita ang pagiging mapagpasensiya sa pamamagitan ng pagpapakalma ng sarili kung kinakailangan o pag-iwas sa mga situwasyong pumupukaw ng negatibong reaksiyon. - Naipaliliwanag na ang pamamahala sa sariling emosyon na nakaaapekto sa pakikipagkapuwa ay pagkakaroon ng sariling kamalayan sa impluwensiya nito sa pakikipag-ugnayan sa kapuwa na nag-iiwas sa kaniya mula sa mga pabigla-biglang reaksiyon.', 2, '13 (3 days)', NULL),
  ('GMRC', 5, 'G5-051', 'Naipakikita ang pagiging mapagpasensiya sa pamamagitan ng pagpapakalma ng sarili kung kinakailangan o pag-iwas sa mga situwasyong pumupukaw ng negatibong reaksiyon. - Naisasakilos ang mga paraan ng wastong pamamahala sa sariling emosyon na nakaaapekto sa pakikipagkapuwa.', 2, '13 (3 days)', NULL),
  ('GMRC', 5, 'G5-052', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng wastong pakikitungo sa mga nakatatanda (elders) anuman ang kanilang estado sa buhay. - Nailalarawan ang sariling mga paraan ng pakikipagkapuwa sa mga nakatatanda (elders).', 2, '14 (3 days)', NULL),
  ('GMRC', 5, 'G5-053', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng wastong pakikitungo sa mga nakatatanda (elders) anuman ang kanilang estado sa buhay. - Naipaliliwanag na ang pakikipagkapuwa sa mga nakatatanda (elders) ay alinsunod sa kanilang taglay na dignidad at sa mga mabuting naiambag sa sariling pagkatao o lipunan.', 2, '14 (3 days)', NULL),
  ('GMRC', 5, 'G5-054', 'Naisasabuhay ang pagiging magalang sa pamamagitan ng wastong pakikitungo sa mga nakatatanda (elders) anuman ang kanilang estado sa buhay. - Nailalapat ang sariling mga paraan ng pakikipagkapuwa sa mga nakatatanda o may gulang (elders).', 2, '14 (3 days)', NULL),
  ('GMRC', 5, 'G5-055', 'Naisasabuhay ang pananampalataya sa pamamagitan ng paggalang sa mga mga simbolo, imahe, at gamit ng pananampalataya o paniniwala ng kapuwa. - Nakakikilala ng mga kahulugan ng mga simbolo, imahe, at gamit sa pananampalataya o paniniwala ng kapuwa.', 3, '1 to 2 (9 days)', NULL),
  ('GMRC', 5, 'G5-056', 'Naisasabuhay ang pananampalataya sa pamamagitan ng paggalang sa mga mga simbolo, imahe, at gamit ng pananampalataya o paniniwala ng kapuwa. - Naipaliliwanag na ang mga simbolo, imahe, at gamit sa pananampalataya o paniniwala ng kapuwa ay mahalagang kilalanin at igalang bilang paalala ng kanilang pananalig sa Diyos.', 3, '1 to 2 (9 days)', NULL),
  ('GMRC', 5, 'G5-057', 'Naisasabuhay ang pananampalataya sa pamamagitan ng paggalang sa mga mga simbolo, imahe, at gamit ng pananampalataya o paniniwala ng kapuwa. - Naisasakilos ang wastong pagkilala sa mga simbolo, imahe, at gamit sa pananampalataya o paniniwala ng kapuwa.', 3, '1 to 2 (9 days)', NULL),
  ('GMRC', 5, 'G5-058', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng regular na pananalangin, pagbasa sa Banal na Aklat at babasahin o katumbas nito sa sariling pananampalataya o paniniwala, at pagsangguni sa mga taong may karunungan at mapagkakatiwalaan. - Natutukoy ang mga paraan ng pangingilatis ng kabutihan bilang katibayan ng pananampalataya.', 3, '3 to 4 (9 days)', NULL),
  ('GMRC', 5, 'G5-059', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng regular na pananalangin, pagbasa sa Banal na Aklat at babasahin o katumbas nito sa sariling pananampalataya o paniniwala, at pagsangguni sa mga taong may karunungan at mapagkakatiwalaan. - Nahihinuha na ang pangingilatis ng kabutihan bilang katibayan ng pananampalataya ay gabay sa pagpapasiya tungo sa pagpili ng kabutihan, paghubog ng mga gawi, pagpapabuti ng mga ugnayan, at pagtupad sa mga tungkulin.', 3, '3 to 4 (9 days)', NULL),
  ('GMRC', 5, 'G5-060', 'Nakapagsasanay sa pananampalataya sa pamamagitan ng regular na pananalangin, pagbasa sa Banal na Aklat at babasahin o katumbas nito sa sariling pananampalataya o paniniwala, at pagsangguni sa mga taong may karunungan at mapagkakatiwalaan. - Nailalapat ang mga paraan ng pangingilatis ng kabutihan bilang katibayan ng pananampalataya.', 3, '3 to 4 (9 days)', NULL),
  ('GMRC', 5, 'G5-061', 'Naisasabuhay ang pagiging maingat sa pamamagitan ng palagiang pagtitiyak na walang magiging sanhi ng anumang sakuna sa loob at labas ng tahanan at paaralan. - Nailalarawan ang mga paraan ng pag-iingat sa kapaligiran kasama ang kapuwa bilang pag-iwas sa sakuna.', 3, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-062', 'Naisasabuhay ang pagiging maingat sa pamamagitan ng palagiang pagtitiyak na walang magiging sanhi ng anumang sakuna sa loob at labas ng tahanan at paaralan. - Naipaliliwanag na ang pag-iingat sa kapaligiran kasama ang kapuwa bilang pag-iwas sa sakuna ay pagtitiyak ng kaligtasan ng lahat upang ingatan ang buhay, ari-arian at lahat ng nakapaligid dito.', 3, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-063', 'Naisasabuhay ang pagiging maingat sa pamamagitan ng palagiang pagtitiyak na walang magiging sanhi ng anumang sakuna sa loob at labas ng tahanan at paaralan. - Naisasakilos ang mga paraan ng pag-iingat sa kapaligiran kasama ang kapuwa bilang pag-iwas sa sakuna.', 3, '5 (5 days)', NULL),
  ('GMRC', 5, 'G5-064', 'Nakapagsasanay sa pagiging maagap sa pamamagitan ng pagdating nang mas maaga o pagpasa ng mga awtput bago ang takdang oras. - Nakakikilala ng mga kilos o gawi ng pagbibigay-galang sa oras ng kapuwa.', 3, '6 (5 days)', NULL),
  ('GMRC', 5, 'G5-065', 'Nakapagsasanay sa pagiging maagap sa pamamagitan ng pagdating nang mas maaga o pagpasa ng mga awtput bago ang takdang oras. - Naipaliliwanag na ang pagbibigay-galang sa oras ng kapuwa bilang isang pagpapahalagang Pilipino ay sumasalamin sa disiplinang pansarili ng lahing pinagmulan na magdudulot ng mabuting pakikipagkapuwa at pagiging produktibo.', 3, '6 (5 days)', NULL),
  ('GMRC', 5, 'G5-066', 'Nakapagsasanay sa pagiging maagap sa pamamagitan ng pagdating nang mas maaga o pagpasa ng mga awtput bago ang takdang oras. - Nailalapat ang mga kilos o gawi ng pagbibigay-galang sa oras ng kapuwa.', 3, '6 (5 days)', NULL),
  ('GMRC', 5, 'G5-067', 'Naisasabuhay ang pagiging magiliw sa kapuwa sa pamamagitan ng palagiang pagbati sa mga kapitbahay. - Natutukoy ang mga wastong pakikisalamuha ng pamilya sa mga kapitbahay.', 3, '7 (5 days)', NULL),
  ('GMRC', 5, 'G5-068', 'Naisasabuhay ang pagiging magiliw sa kapuwa sa pamamagitan ng palagiang pagbati sa mga kapitbahay. - Napatutunayan na ang wastong pakikisalamuha ng pamilya sa mga kapitbahay ay nakapagpapatatag ng sariling pagkakakilanlan ng tao bilang panlipunang nilalang.', 3, '7 (5 days)', NULL),
  ('GMRC', 5, 'G5-069', 'Naisasabuhay ang pagiging magiliw sa kapuwa sa pamamagitan ng palagiang pagbati sa mga kapitbahay. - Nailalapat ang mga sariling paraan ng mga wastong pakikisalamuha ng pamilya sa mga kapitbahay.', 3, '7 (5 days)', NULL),
  ('GMRC', 5, 'G5-070', 'Nakapagsasanay sa pagiging masunurin sa pamamagitan ng wastong pagtugon sa mga situwasyon na may kaugnayan sa mga alituntunin ng pamayanan ayon sa kaniyang kakayahan. - Naiisa-isa ang mga katangian ng mabuting tagasunod ng mga alituntunin ng pamayanan.', 3, '8 (5 days)', NULL),
  ('GMRC', 5, 'G5-071', 'Nakapagsasanay sa pagiging masunurin sa pamamagitan ng wastong pagtugon sa mga situwasyon na may kaugnayan sa mga alituntunin ng pamayanan ayon sa kaniyang kakayahan. - Napagtitibay na ang mga katangian ng mabuting tagasunod ng mga alituntunin ng pamayanan ay susi upang maging maayos ang pagpapatupad ng mga batas na nagtitiyak sa kapakanan at kapayapaan ng mga mamamayan.', 3, '8 (5 days)', NULL),
  ('GMRC', 5, 'G5-072', 'Nakapagsasanay sa pagiging masunurin sa pamamagitan ng wastong pagtugon sa mga situwasyon na may kaugnayan sa mga alituntunin ng pamayanan ayon sa kaniyang kakayahan. - Naisasakilos ang mga katangian ng mabuting tagasunod ng mga alituntunin ng pamayanan.', 3, '8 (5 days)', NULL),
  ('GMRC', 5, 'G5-073', 'Naisasabuhay ang pag-asa sa pamamagitan ng taimtim na pananalangin upang malampasan ang mga hamon ng pamayanan. - Nakapagpapahayag ng mga mabuting epekto ng pananampalataya ng pamayanan sa panahon ng pangangailangan.', 3, '9 (5 days)', NULL),
  ('GMRC', 5, 'G5-074', 'Naisasabuhay ang pag-asa sa pamamagitan ng taimtim na pananalangin upang malampasan ang mga hamon ng pamayanan. - Napaninindigan na ang pananampalataya bilang daluyan ng pag-asa ng pamayanan ay pinakamataas na antas na pinagmumulan ng katatagan ng loob at katiyakan na may laging handang tumulong sa kanila sa panahon ng pangangailangan.', 3, '9 (5 days)', NULL),
  ('GMRC', 5, 'G5-075', 'Naisasabuhay ang pag-asa sa pamamagitan ng taimtim na pananalangin upang malampasan ang mga hamon ng pamayanan. - Nailalapat ang sariling pananampalataya sa panahon ng pangangailangan ng pamayanan.', 3, '9 (5 days)', NULL),
  ('GMRC', 5, 'G5-076', 'Nakapagsasanay sa pagiging positibo sa buhay sa pamamagitan ng pagbibigay ng mas malaking pagpapahalaga sa mga nagawang kabutihan kaysa sa mga kamalian. - Nakapagsasalaysay ng mga gawain na nagpapatingkad ng positibong pagtingin sa mga mamamayan batay sa sariling pananampalataya.', 3, '10 (5 days)', NULL),
  ('GMRC', 5, 'G5-077', 'Nakapagsasanay sa pagiging positibo sa buhay sa pamamagitan ng pagbibigay ng mas malaking pagpapahalaga sa mga nagawang kabutihan kaysa sa mga kamalian. - Napatutunayan na ang positibong pagtingin sa mga mamamayan batay sa sariling pananampalataya ay pagkilala sa kanilang kakayahang gumawa ng mabuti ayon sa pagkalalang sa kanila ng Diyos at mapanatili ang matiwasay na ugnayan.', 3, '10 (5 days)', NULL),
  ('GMRC', 5, 'G5-078', 'Nakapagsasanay sa pagiging positibo sa buhay sa pamamagitan ng pagbibigay ng mas malaking pagpapahalaga sa mga nagawang kabutihan kaysa sa mga kamalian. - Nakapagbabahagi ng mga positibong pagtingin sa mga mamamayan batay sa sariling pananampalataya.', 3, '10 (5 days)', NULL)
) AS v(area, grade_level, lc_code, competency_text, term, week, domain)
JOIN procurements.sms_learning_areas a ON lower(btrim(a.name)) = lower(btrim(v.area))
ON CONFLICT (learning_area_id, grade_level, lc_code) DO NOTHING;

/* Verification: after all 22 parts, seeded_entries = 6718. */
SELECT count(*) AS seeded_entries,
       count(DISTINCT learning_area_id) AS learning_areas
FROM procurements.sms_competency_catalogue
WHERE lc_code ~ '^(K|G[0-9]+)-[0-9]{3}$';
